sp_widget.client_script:
api.controller = function() {

    var c = this;

    c.form = {
        category: "",
        description: ""
    };

    c.submitting = false;
    c.successMessage = "";
    c.errorMessage = "";

	c.getPriorityLabel = function() {

    if (!c.form.category)
        return "";

    var map = {
        payroll: "High",
        benefits: "Medium",
        leave: "Medium",
        employee_relations: "High",
        general: "Low",
        others: "Low"
    };

    return map[c.form.category] || "";
};


    c.submitRequest = function() {

        c.successMessage = "";
        c.errorMessage = "";


        if (!c.form.category ||
            !c.form.description) {

            c.errorMessage =
                "Please complete all required fields.";

            return;
        }


        c.submitting = true;


        c.server.get({

            action: 'create_case',

            category:
                c.form.category,

            description:
                c.form.description

        }).then(function(response) {

            c.submitting = false;

            var result =
                response.data.result;


            if (result && result.success) {

                c.successMessage =
                    "HR Request " +
                    result.number +
                    " created successfully.";

                c.form.category = "";
                c.form.description = "";

            } else {

                c.errorMessage =
                    result && result.message
                    ? result.message
                    : "Unable to create HR request.";
            }

        }, function() {

            c.submitting = false;

            c.errorMessage =
                "An error occurred while creating the request.";

        });

    };

};

sp_widget.css:
.hod-raise-case-page {
  max-width: 900px;
  margin: 30px auto;
  padding: 0 20px;
  color: #0f1b45;
}

.page-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
}

.page-header h2 {
  margin: 0 0 6px;
  font-size: 28px;
  font-weight: 700;
}

.page-header p {
  margin: 0;
  color: #7b8497;
}

.back-link {
  color: #1769e0;
  text-decoration: none;
}

.request-card {
  background: #ffffff;
  border: 1px solid #e2e7ef;
  border-radius: 14px;
  padding: 26px;
  box-shadow: 0 3px 10px rgba(0,0,0,.04);
}

.form-group {
  margin-bottom: 20px;
}

.form-group label {
  display: block;
  font-weight: 600;
  margin-bottom: 8px;
}

.form-group label span {
  color: #e53935;
}

.form-control {
  width: 100%;
  border: 1px solid #dce2eb;
  border-radius: 8px;
  padding: 11px 12px;
  outline: none;
  background: #ffffff;
}

.description-box {
  min-height: 140px;
  resize: vertical;
}

.form-actions {
  display: flex;
  justify-content: flex-end;
}

.submit-btn {
  background: #17a673;
  color: white;
  border: none;
  border-radius: 8px;
  padding: 11px 20px;
  font-weight: 600;
  cursor: pointer;
}

.submit-btn:disabled {
  opacity: .6;
  cursor: not-allowed;
}

.success-box {
  margin-top: 18px;
  padding: 14px;
  background: #e6f7ef;
  color: #15724f;
  border-radius: 8px;
}

.error-box {
  margin-top: 18px;
  padding: 14px;
  background: #fdeaea;
  color: #b42318;
  border-radius: 8px;
}

.priority-readonly {
  background: #f5f7fa;
  color: #596579;
  cursor: not-allowed;
}

.priority-help {
  display: block;
  margin-top: 6px;
  color: #7b8497;
  font-size: 12px;
}

select.form-control {
  height: 44px;
  line-height: 22px;
  padding: 10px 12px;
  font-size: 14px;
}

.form-control {
  box-sizing: border-box;
}

@media (max-width: 700px) {

  .page-header {
    display: block;
  }

  .back-link {
    display: inline-block;
    margin-top: 12px;
  }
}

sp_widget.script:
(function() {

    data.result = null;

    if (!input || input.action != 'create_case')
        return;


    var category =
        (input.category || '').toString();

    var description =
        (input.description || '').toString();


    if (!category || !description) {

        data.result = {
            success: false,
            message: "Please complete all required fields."
        };

        return;
    }


    var allowedCategories = [
        'payroll',
        'benefits',
        'leave',
        'employee_relations',
        'general',
        'others'
    ];


    if (allowedCategories.indexOf(category) == -1) {

        data.result = {
            success: false,
            message: "Invalid category."
        };

        return;
    }


    var caseGR =
        new GlideRecord(
            'x_snc_unified_hr_0_hr_case'
        );

    caseGR.initialize();

    caseGR.setValue(
        'request_by',
        gs.getUserID()
    );

    caseGR.setValue(
        'category',
        category
    );

    caseGR.setValue(
        'description',
        description
    );

    caseGR.setValue(
        'status',
        'open'
    );


    // DO NOT SET PRIORITY HERE
    // Existing Business Rule / Flow
    // will assign priority based on category.


    var newSysId = caseGR.insert();


    if (!newSysId) {

        data.result = {
            success: false,
            message: "Unable to create the HR request."
        };

        return;
    }


    var createdGR =
        new GlideRecord(
            'x_snc_unified_hr_0_hr_case'
        );

    var caseNumber = "";

    if (createdGR.get(newSysId)) {

        caseNumber =
            createdGR.getDisplayValue('number');
    }


    data.result = {
        success: true,
        number: caseNumber,
        sys_id: newSysId
    };

})();
